head.script:
scwin.btn_reset_onclick = function(e) {
    dataList1.removeColumnFilterAll();
    var jsonData2 = [{
        col1: "0001",
        col2: "0001",
        col3: "0001",
        col4: "0001"
    }, {
        col1: "0002",
        col2: "0002",
        col3: "0002",
        col4: "0002"
    }, {
        col1: "0003",
        col2: "0003",
        col3: "0003",
        col4: "0003"
    }, {
        col1: "0004",
        col2: "0004",
        col3: "0004",
        col4: "0004"
    }, {
        col1: "0005",
        col2: "0005",
        col3: "0005",
        col4: "0005"
    }, {
        col1: "0006",
        col2: "0006",
        col3: "0006",
        col4: "0006"
    }, {
        col1: "0007",
        col2: "0007",
        col3: "0007",
        col4: "0007"
    }];
    dataList1.setJSON(jsonData2);
};
scwin.__clickFilter = function(p) {
    var el = WebSquare.wUnit.getDomById($p.id + "gridView1_customFilter_list").getElementsByClassName('w2list_listRow');
    return el[p].childNodes[0].click();
}
scwin.__checkExceptFilter = function(val) {
    var count = 0;
    WebSquare.wUnit.getJq("#gridView1_body_tbody tr").find("td").not("#_headerRowStatus").each(function() {
        if (WebSquare.wUnit.getJq(this).text() == val) {
            count++;
        }
    });
    return count == 0;
}
scwin.__isShowFilter = function(val) {
    var div = WebSquare.wUnit.getJq("#gridView1_customFilter_list").find(".w2list_listRow");
    return div.length == val;
}
scwin.__isShowInitData = function() {
    return WebSquare.wUnit.getJq("#gridView1_body_tbody tr").length == dataList1.getRowCount();
}
scwin.unitTest = function() {
    //Unit
    WebSquare.wUnit.start();
    WebSquare.wUnit.addCommand("pause", "500");
    // Test step 1. 브라우저에서 name1 컬럼의 '0001' 을 필터를 체크해지한다.
    //1. In your browser, uncheck the '0001' filter in the name1 column.    
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('gridView1_column11_filter').click()");
    WebSquare.wUnit.addCommand("pause", "1000");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('gridView1_customFilter_list').querySelectorAll('div')[2].click()");
    WebSquare.wUnit.addCommand("pause", "1000");

    WebSquare.wUnit.addCommand("assert", "scwin.__isShowFilter(4)", "true");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('gridView1_column11_filter').click()");
    WebSquare.wUnit.addCommand("pause", "1000");
    //Verify step 1. '0001' 데이터가 필터해지되면서 '0001' 데이터를 제외한 '0002' 데이터가 표시된다.
    //1. '0001' data is filtered and '0002' data is displayed except for '0001' data.
    WebSquare.wUnit.addCommand("assert", "scwin.__checkExceptFilter('0001')", "true");
    WebSquare.wUnit.addCommand("pause", "1000");
    //Test step 2. 재조회(필터제거) 버튼을 클릭한다.
    //2. Click the Re-query (Remove Filter) button.
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('btn_reset').click()");
    WebSquare.wUnit.addCommand("pause", "1000");
    //Verify step 2. 필터가 초기화되면서 초기화 데이터가 표시된다.
    //2. The filter is initialized and the initialization data is displayed.
    WebSquare.wUnit.addCommand("assert", "scwin.__isShowInitData()", "true");
    WebSquare.wUnit.addCommand("pause", "1000");
    //Test step 3. 다시 name1 컬럼의 '0001' 을 필터를 체크해지한다.
    //3. Check the filter '0001' in the name1 column again.
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('gridView1_column11_filter').click()");
    WebSquare.wUnit.addCommand("pause", "1000");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('gridView1_customFilter_list').querySelectorAll('div')[2].click()");
    WebSquare.wUnit.addCommand("assert", "scwin.__isShowFilter(9)", "true");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('gridView1_column11_filter').click()");
    WebSquare.wUnit.addCommand("pause", "1000");
    //Verify step 3. '0001' 데이터가 필터해지되면서 '0001' 데이터를 제외한 나머지 데이터가 표시된다.
    //3. '0001' data is filtered out, and the remaining data except '0001' data is displayed.
    WebSquare.wUnit.addCommand("assert", "scwin.__checkExceptFilter('0001')", "true");
    WebSquare.wUnit.addCommand("pause", "1000");
    //Run test and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.unitTest();

scwin.onpageload = function() {
    window.jsonData = [{
        col1: "0001",
        col2: "0001",
        col3: "0001",
        col4: "0001"
    }, {
        col1: "0002",
        col2: "0002",
        col3: "0002",
        col4: "0002"
    }];
    dataList1.setJSON(jsonData);
    //Function unitTest
    //Created By: Sang.do
    //Created By: 08-Feb-2018
    window.time = 1;
    //end unitTest
}
